-- ==== view v_item_difficulty — 20260917000100_testers_only.sql

create or replace view public.v_item_difficulty as
    select item_id, p_correct
      from public.item_stats
     where answered >= 8
       and p_correct is not null
       and (select public.is_tester());

comment on view public.v_item_difficulty is
    'Per-item success rate, over the first answers of at least eight different '
    'people. A property of the question, never of a person, and never displayed.';


-- ==== view v_my_daily — 20260913000300_stats_and_selection.sql

create view public.v_my_daily
with (security_invoker = on) as
select
    (a.answered_at at time zone 'Asia/Tokyo')::date       as day,
    count(*)                                              as answered,
    count(*) filter (where a.is_correct)                  as correct
from public.attempts a
group by 1;


-- ==== view v_my_day — 20260930000300_the_door_is_on_the_answer.sql

create or replace view public.v_my_day
with (security_invoker = on) as
with today as (
    select count(*)::int as answered
      from public.attempts a
     where a.user_id = (select auth.uid())
       and a.answered_at >= ((now() at time zone 'Asia/Tokyo')::date::timestamp
                             at time zone 'Asia/Tokyo')
)
select
    coalesce((select p.daily_goal from public.profiles p where p.id = (select auth.uid())), 10)
                                                        as goal,
    today.answered                                      as answered_today,
    (select public.is_unlimited())                      as unlimited,
    case when (select public.is_unlimited()) then null
         else (select public.my_daily_max()) end        as max_today,
    case when (select public.is_unlimited()) then null
         else greatest((select public.my_daily_max()) - today.answered, 0) end
                                                        as left_today,
    (select public.my_goal_max())                       as goal_max
from today;

comment on view public.v_my_day is
    'Today, for this learner: the goal, what is answered, whether the ceiling '
    'is lifted, the ceiling, how many more the queue will serve, and — for the '
    'one account that may size its own day — how large a set it may ask for. '
    'Days end at midnight in Japan, as the streak counts them.';


-- ==== view v_my_levels — 20260927000100_a_new_question_not_the_same_one.sql

create or replace view public.v_my_levels
with (security_invoker = on) as
select s.section,
       coalesce(sl.level, 'J2')       as level,
       coalesce(sl.changed_at, now()) as changed_at,
       coalesce(sl.moves, 0) > 0
       or (sl.level is not null
           and ev.level_window >= 5
           and ev.answered >= least(10, ev.level_window)) as placed
from (values ('choukai'), ('choudokkai'), ('dokkai')) as s(section)
left join public.section_levels sl
       on sl.user_id = (select auth.uid()) and sl.section = s.section
left join lateral public.level_evidence(s.section) ev on true;


-- ==== view v_my_review_load — 20260916000500_shared_bank_and_spacing.sql

create view public.v_my_review_load
with (security_invoker = on) as
select
    count(*) filter (where r.due_at <= now())::int as due_now,
    count(*)::int                                  as tracked,
    min(r.due_at) filter (where r.due_at > now())  as next_due_at
from public.review_schedule r;


-- ==== view v_my_role_traps — 20260927000100_a_new_question_not_the_same_one.sql

create or replace view public.v_my_role_traps
with (security_invoker = on) as
with caught as (
    select a.chosen_role                as role,
           count(*)                     as times_chosen,
           max(a.answered_at)           as last_chosen_at,
           count(*) filter (where a.answered_at >= now() - interval '30 days')::int
                                        as recent_times
      from public.attempts a
      join public.items i on i.id = a.item_id and i.is_published
     where not a.is_correct
     group by a.chosen_role
),
met as (
    select o.role,
           count(*)::int as times_met,
           count(*) filter (where a.answered_at >= now() - interval '30 days')::int
                         as recent_met
      from public.attempts a
      join public.items i on i.id = a.item_id and i.is_published
      join public.item_options o on o.item_id = a.item_id and o.position <> i.correct_index
     group by o.role
)
select c.role, c.times_chosen, c.last_chosen_at, c.recent_times,
       m.times_met, m.recent_met
  from caught c
  left join met m on m.role = c.role;


-- ==== view v_my_tag_stats — 20260918000100_queue_keeps_its_promises.sql

create or replace view public.v_my_tag_stats
with (security_invoker = on) as
with tagged as (
    select 'function' as axis, i.function as tag, a.is_correct, a.answered_at from public.attempts a join public.items i on i.id = a.item_id where i.function is not null
    union all
    select 'relation', i.relation, a.is_correct, a.answered_at from public.attempts a join public.items i on i.id = a.item_id where i.relation is not null
    union all
    select 'setting',  i.setting,  a.is_correct, a.answered_at from public.attempts a join public.items i on i.id = a.item_id where i.setting is not null
    union all
    select 'channel',  i.channel,  a.is_correct, a.answered_at from public.attempts a join public.items i on i.id = a.item_id where i.channel is not null
)
select
    axis,
    tag,
    count(*)                                   as answered,
    count(*) filter (where is_correct)         as correct,
    count(*) filter (where is_correct)::numeric / count(*) as accuracy,
    count(*) filter (where answered_at >= now() - interval '30 days')::int
                                               as recent_answered,
    (coalesce(sum(power(0.5, extract(epoch from now() - answered_at) / (30 * 86400)))
                  filter (where is_correct), 0)
     / nullif(sum(power(0.5, extract(epoch from now() - answered_at) / (30 * 86400))), 0)
    )::numeric                                 as recent_accuracy
from tagged
group by axis, tag;


-- ==== view v_my_type_stats — 20260918000100_queue_keeps_its_promises.sql

create or replace view public.v_my_type_stats
with (security_invoker = on) as
select
    t.id                                                as item_type,
    t.label_ja,
    t.section,
    t.sort_order,
    count(a.id)                                         as answered,
    count(a.id) filter (where a.is_correct)             as correct,
    case when count(a.id) > 0
         then count(a.id) filter (where a.is_correct)::numeric / count(a.id)
    end                                                 as accuracy,
    max(a.answered_at)                                  as last_answered_at,
    count(a.id) filter (where a.answered_at >= now() - interval '30 days')::int
                                                        as recent_answered,
    -- Null when nothing was answered (the denominator is null), 0 when it was
    -- all wrong (a filtered sum over no rows is null, hence the coalesce).
    (coalesce(sum(power(0.5, extract(epoch from now() - a.answered_at) / (30 * 86400)))
                  filter (where a.is_correct), 0)
     / nullif(sum(power(0.5, extract(epoch from now() - a.answered_at) / (30 * 86400))), 0)
    )::numeric                                          as recent_accuracy
from public.item_types t
left join public.items i on i.item_type = t.id
left join public.attempts a on a.item_id = i.id
group by t.id, t.label_ja, t.section, t.sort_order;


-- ==== function adjust_level — 20260927000100_a_new_question_not_the_same_one.sql

create or replace function public.adjust_level()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
    v_section text;
    ev        record;
    v_next    text;
    v_overall text;
begin
    select it.section
      into v_section
      from public.items i
      join public.item_types it on it.id = i.item_type
     where i.id = new.item_id;
    if v_section is null then
        return new;
    end if;

    -- The very first answer seeds all three sections at once, as before, so a
    -- strong reader does not meet 聴解 already at J1.
    insert into public.section_levels (user_id, section, level)
    select new.user_id, s.section,
           coalesce((select p.target_level from public.profiles p where p.id = new.user_id), 'J2')
    from (values ('choukai'), ('choudokkai'), ('dokkai')) as s(section)
    on conflict (user_id, section) do nothing;

    select * into ev from public.level_evidence(v_section);

    if ev.level_window >= 5 and ev.answered >= ev.level_window then
        if ev.correct * 10 >= ev.level_window * 8 then
            v_next := case ev.level when 'J3' then 'J2' when 'J2' then 'J1' end;
        elsif ev.correct * 10 <= ev.level_window * 4 then
            v_next := case ev.level when 'J1' then 'J2' when 'J2' then 'J3' end;
        end if;
    end if;

    if v_next is not null
       and public.questions_left(new.user_id, v_section, v_next) < 5 then
        v_next := null;
    end if;

    if v_next is not null then
        update public.section_levels
           set level = v_next, changed_at = now(), moves = moves + 1
         where user_id = new.user_id and section = v_section;
    end if;

    -- `profiles.target_level` stays the one-line summary: the middle of the
    -- three. It decides nothing.
    select sl.level into v_overall
      from public.section_levels sl
     where sl.user_id = new.user_id
     order by case sl.level when 'J3' then 0 when 'J2' then 1 else 2 end
     offset 1 limit 1;

    if v_overall is not null then
        update public.profiles
           set target_level     = v_overall,
               level_changed_at = case when target_level is distinct from v_overall
                                       then now() else level_changed_at end,
               updated_at       = now()
         where id = new.user_id
           and target_level is distinct from v_overall;
    end if;
    return new;
end;
$$;

comment on function public.adjust_level is
    'Move the level of the section this answer belongs to, on level_evidence(): the '
    'latest unaided first attempts at that level, ten or twenty of them but never '
    'more than the level has questions for, and never fewer than five. Nobody is '
    'moved into a level with fewer than five questions left to meet.';


