-- ==== function keep_the_daily_goal_under_its_ceiling — 20260930000200_four_columns_of_a_profile.sql

create or replace function public.keep_the_daily_goal_under_its_ceiling()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
    v_max integer;
begin
    -- Only the app: a signed-in request, as PostgREST makes one, writing its
    -- own profile. A migration, a fixture, a definer function or the owner with
    -- the service role is none of those and is not what this is guarding.
    if current_user <> 'authenticated'
       or (select auth.uid()) is distinct from new.id then
        return new;
    end if;
    -- And only when the goal is what is being written. A row is not re-judged
    -- every time something else on it moves: a goal of forty set while the
    -- account had a ceiling of sixty would otherwise make every later write to
    -- that profile fail the day the ceiling came off, which is a strange way
    -- for an exam date to stop saving.
    if tg_op = 'UPDATE' and new.daily_goal is not distinct from old.daily_goal then
        return new;
    end if;
    -- The size of a day is the owner's to give, one account at a time. Without
    -- a number on this account's tester row it is not the learner's to change
    -- at all, not even below the fifteen: ten is the product, not a setting.
    v_max := (select public.my_goal_max());
    if v_max is null then
        raise exception 'the size of the day is not this account''s to choose'
            using errcode = 'insufficient_privilege';
    end if;
    if new.daily_goal > v_max then
        raise exception 'a daily goal of % is above this account''s ceiling of %',
            new.daily_goal, v_max;
    end if;
    return new;
end;
$$;

comment on function public.keep_the_daily_goal_under_its_ceiling is
    'The size of the day, enforced where the client cannot get past it. A client '
    'may change profiles.daily_goal only on the account whose tester row carries '
    'max_daily_goal, and only up to it; everybody else''s goal is not theirs to '
    'change. Judges a goal being written, never an existing row.';


-- ==== function level_evidence — 20260927000100_a_new_question_not_the_same_one.sql

create or replace function public.level_evidence(p_section text)
returns table (
    level        text,
    since        timestamptz,
    level_window integer,
    answered     integer,
    correct      integer
)
language sql
stable
set search_path = ''
as $$
    with me as (
        select (select auth.uid()) as id
    ),
    cur as (
        select coalesce(sl.level, 'J2')              as level,
               coalesce(sl.changed_at, '-infinity')  as since
          from (select 1) one
          left join public.section_levels sl
                 on sl.user_id = (select id from me) and sl.section = p_section
    ),
    firsts as (
        select a.id, a.item_id, a.is_correct, a.answered_at, i.level,
               (a.replays > 0 or a.peeked) as helped
          from public.attempts a
          join public.items i on i.id = a.item_id
          join public.item_types it on it.id = i.item_type
         where a.user_id = (select id from me)
           and it.section = p_section
           and i.is_published
           and not exists (
                   select 1 from public.attempts b
                    where b.user_id = a.user_id
                      and b.item_id = a.item_id
                      and (b.answered_at, b.id) < (a.answered_at, a.id))
    ),
    shelf as (
        select count(*)::int as n
          from public.items i
          join public.item_types it on it.id = i.item_type
         cross join cur
         where it.section = p_section
           and i.level = cur.level
           and i.is_published
           and (not it.needs_picture
                or exists (select 1 from public.scenes sc
                            where sc.id = i.scene_id and sc.image_path is not null))
           and not exists (select 1 from firsts f
                            where f.item_id = i.id and f.answered_at < cur.since)
    ),
    win as (
        select least(case when (select count(*) from firsts) < 20 then 10 else 20 end,
                     (select n from shelf)) as w
    ),
    recent as (
        select f.is_correct
          from firsts f
         cross join cur
         where f.level = cur.level
           and f.answered_at >= cur.since
           and not f.helped
         order by f.answered_at desc, f.id desc
         limit (select w from win)
    )
    select cur.level,
           cur.since,
           (select w from win),
           (select count(*)::int from recent),
           (select count(*) filter (where recent.is_correct)::int from recent)
      from cur
     -- The same door as everything else: a non-tester is answered with nothing.
     where (select public.is_tester());
$$;

comment on function public.level_evidence is
    'The evidence a section''s level is judged on, for the caller: the level, since '
    'when, the window (ten, or twenty with a record, never more than the questions '
    'the level has left, and unjudgeable below five), and how many of the latest '
    'unaided first attempts at that level are in it and right.';


